    const ordered=state.turnOrder.map(player=>state.answers.find(a=>a.player===player)||({player,choice:null,correct:false,elapsed:0,bonus:0,points:0,question:state.gameFormat==='individual'?state.roundQuestionMap[player]:(state.currentDisplayedQuestion||state.questions[state.round]),skipped:true,skipReason:'missing'})).sort((a,b)=>Number(b.points||0)-Number(a.points||0)||Number(a.elapsed||0)-Number(b.elapsed||0));
