      $('#round-results').innerHTML=ordered.map(a=>`<div class="result-row ${a.correct?'':'missed'}"><span class="result-avatar">${escapeHTML(a.player.slice(0,1).toLocaleUpperCase('pt-BR'))}</span><span class="result-name">${escapeHTML(a.player)}</span><span class="result-detail">${a.skipped?'Não jogou · sem penalidade':a.correct?`Acertou · ${Number(a.elapsed||0).toFixed(1)}s`:'Errou'}</span><span class="result-points">+${Number(a.points)||0} pts</span></div>`).join('');
