    const rows=state.players.map(name=>{
      const old=Number(before[name])||0,now=Number(state.scores[name])||0,delta=now-old;
      const sign=delta>0?'+':'';
      return `<div class="roulette-impact-row"><span class="roulette-impact-player">${escapeHTML(name)}</span><span class="roulette-impact-before">${old} <small>PTS</small></span><span class="roulette-impact-arrow">→</span><strong class="roulette-impact-after ${delta>0?'positive':delta<0?'negative':'neutral'}">${now} <small>PTS</small></strong><span class="roulette-impact-delta ${delta>0?'positive':delta<0?'negative':'neutral'}">${delta===0?'SEM ALTERAÇÃO':`${sign}${delta} PTS`}</span></div>`;
    }).join('');
    const titles={plus:'PONTOS ADICIONADOS',minus:'PONTOS PERDIDOS',neutral:'NADA MUDOU NO PLACAR',swap:'TROCA DE PONTUAÇÕES',crown:'COROA CONQUISTADA',toll:'PEDÁGIO COBRADO',tax:'IMPOSTO PAGO',skip:'FORA DA RODADA FINAL'};
    const explanations={plus:`${state.roulettePlayer} recebeu 5 pontos.`,minus:`${state.roulettePlayer} perdeu 5 pontos.`,neutral:`${state.roulettePlayer} manteve sua pontuação.`,swap:details||'As pontuações completas foram trocadas.',crown:details||`Categoria escolhida: ${state.rouletteTheme||'—'}.`,toll:`${state.roulettePlayer} recebeu 1 ponto de cada adversário.`,tax:`${state.roulettePlayer} transferiu 1 ponto para cada adversário.`,skip:`${state.roulettePlayer} não poderá responder à pergunta da última rodada. A pontuação acumulada foi mantida.`};
